@import url('https://fonts.googleapis.com/css2?family=inter:wght@400;600;700&display=swap');

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #1A1A1A;
  font-family: "Inter", sans-serif;
}

#ad-320x480 {
  width: 320px;
  height: 480px;
  position: relative;
  overflow: hidden;
  background: #FFED00;
  display: flex;
  flex-direction: column;
  align-items: center;
}

/* Background decoration */
.bg-deco {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  background:
    radial-gradient(circle at 88% 8%, rgba(227,0,11,0.16) 0%, transparent 52%),
    radial-gradient(circle at 12% 88%, rgba(0,109,183,0.12) 0%, transparent 48%);
}

.bg-deco::after {
  content: "";
  position: absolute;
  top: -55px;
  right: -55px;
  width: 190px;
  height: 190px;
  border-radius: 50%;
  border: 20px solid rgba(227,0,11,0.18);
  animation: spin-ring 16s linear infinite;
}

@keyframes spin-ring {
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
}

/* Header */
.ad-header {
  position: relative;
  z-index: 10;
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px 8px;
  background: #E3000B;
  box-shadow: 0 2px 8px rgba(0,0,0,0.28);
  flex-shrink: 0;
}

.ad-logo {
  height: 30px;
  width: auto;
  display: block;
  flex-shrink: 0;
}

.eyebrow {
  font-family: "Inter", sans-serif;
  font-weight: 700;
  font-size: 10px;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: #FFED00;
  background: rgba(0,0,0,0.22);
  padding: 3px 8px;
  border-radius: 30px;
}

/* Headline block */
.headline-block {
  position: relative;
  z-index: 10;
  width: 100%;
  padding: 10px 16px 2px;
  text-align: center;
  flex-shrink: 0;
}

.headline {
  font-family: "Inter", sans-serif;
  font-weight: 700;
  font-size: 22px;
  line-height: 1.15;
  color: #000000;
  text-align: center;
}

.headline em {
  font-style: normal;
  color: #E3000B;
}

.subhead {
  font-family: "Inter", sans-serif;
  font-weight: 600;
  font-size: 12px;
  color: #1A1A1A;
  margin-top: 3px;
  letter-spacing: 0.02em;
}

/* Carousel */
.carousel-wrap {
  position: relative;
  z-index: 10;
  width: 288px;
  height: 208px;
  margin: 8px auto 0;
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 4px 18px rgba(0,0,0,0.30);
  background: #FFFFFF;
  flex-shrink: 0;
}

.carousel-track {
  display: flex;
  width: 300%;
  height: 100%;
  transition: transform 0.45s cubic-bezier(0.4,0,0.2,1);
  will-change: transform;
}

.slide {
  width: calc(100% / 3);
  height: 100%;
  position: relative;
  overflow: hidden;
  background: #F2F2F2;
  flex-shrink: 0;
}

.slide-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  display: block;
  transition: transform 0.5s ease;
}

.slide:hover .slide-img {
  transform: scale(1.04);
}

.slide-label {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  background: rgba(0,0,0,0.52);
  color: #FFFFFF;
  font-family: "Inter", sans-serif;
  font-weight: 600;
  font-size: 10px;
  text-align: center;
  padding: 5px 8px;
  letter-spacing: 0.03em;
}

/* Dots */
.carousel-dots {
  position: absolute;
  bottom: 8px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 6px;
  z-index: 20;
}

.dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  border: none;
  background: rgba(255,255,255,0.45);
  cursor: pointer;
  padding: 0;
  transition: background 0.3s, transform 0.3s;
}

.dot.active {
  background: #FFED00;
  transform: scale(1.35);
}

/* Arrows */
.carousel-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 26px;
  height: 26px;
  border-radius: 50%;
  border: none;
  background: rgba(255,255,255,0.88);
  color: #E3000B;
  font-size: 20px;
  line-height: 1;
  cursor: pointer;
  z-index: 20;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  font-weight: 700;
  box-shadow: 0 2px 8px rgba(0,0,0,0.22);
  transition: background 0.2s, transform 0.2s;
}

.carousel-arrow:hover {
  background: #FFED00;
  transform: translateY(-50%) scale(1.12);
}

.arrow-prev { left: 6px; }
.arrow-next { right: 6px; }

/* Body copy */
.body-copy {
  position: relative;
  z-index: 10;
  font-family: "Inter", sans-serif;
  font-size: 11px;
  font-weight: 500;
  color: #1A1A1A;
  text-align: center;
  margin-top: 8px;
  padding: 0 16px;
  letter-spacing: 0.02em;
  flex-shrink: 0;
}

/* CTA */
.cta-btn {
  position: relative;
  z-index: 10;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-top: 10px;
  padding: 0 26px;
  height: 40px;
  border-radius: 40px;
  background: #E3000B;
  text-decoration: none;
  box-shadow: 0 4px 14px rgba(227,0,11,0.38);
  transition: transform 0.18s ease, box-shadow 0.18s ease, background 0.18s ease;
  animation: pulse-cta 2.8s ease-in-out infinite;
  flex-shrink: 0;
  margin-bottom: 28px;
}

.cta-btn:hover {
  background: #000000;
  box-shadow: 0 6px 18px rgba(0,0,0,0.38);
  transform: scale(1.06);
  animation: none;
}

@keyframes pulse-cta {
  0%, 100% { box-shadow: 0 4px 14px rgba(227,0,11,0.38); }
  50%       { box-shadow: 0 4px 22px rgba(227,0,11,0.65); }
}

.cta-label {
  font-family: "Inter", sans-serif;
  font-weight: 700;
  font-size: 12px;
  color: #FFFFFF;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  pointer-events: none;
}

/* Footer */
.ad-footer {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 10;
  background: rgba(0,0,0,0.70);
  padding: 4px 10px;
  text-align: center;
}

.ad-footer span {
  font-family: "Inter", sans-serif;
  font-size: 7px;
  color: rgba(255,255,255,0.72);
  line-height: 1.4;
  display: block;
}

@media (prefers-reduced-motion: reduce) {
  .carousel-track { transition: none; }
  .bg-deco::after  { animation: none; }
  .cta-btn         { animation: none; }
  .slide-img       { transition: none; }
}

